package presentation

import v "github.com/Naenier/ED-Copilot/internal/value"

func RanksPage(state M) Page {
	p := Page{Title: "Ранги", Description: "Прогресс командира, способы повышения и доступные награды.", Columns: []string{"Направление ранга", "Ранг", "Следующий ранг", "Прогресс, %"}, Rows: []Row{}}
	for _, rank := range v.Rows(v.At(state, "ranks", "disciplines")) {
		p.Rows = append(p.Rows, row(rank, []string{v.Text(rank["title"], "—"), v.Text(rank["rankName"], "—"), v.Text(rank["nextRankName"], "—"), Number(rank["progressPercent"])}, ""))
	}
	return p
}

func PoliticsPage(state M) Page {
	p := Page{Title: "Политика", Description: "Цели сообщества, державы, фракции и конфликты систем.", Columns: []string{"Система", "Состояние"}, Rows: []Row{}}
	for _, system := range v.Rows(v.At(state, "politics", "systems")) {
		p.Rows = append(p.Rows, row(system, []string{v.Text(system["name"], "—"), v.Text(v.At(system, "powerplay", "state"), v.At(system, "thargoid", "state"), "Неизвестно")}, ""))
	}
	return p
}

